# Content with portions generated by generative AI platform

import base64
import json
import os
import ssl
import sys
import time
import urllib.error
import urllib.request

IMAGES_PATH = "/inventory/v1/images"
REFRESH_PATH = "/token/jwt/v1/refresh"


def log(message):
    print(time.strftime("%Y-%m-%d %H:%M:%S"), message, flush=True)


def read_token_pair(path):
    with open(path, encoding="utf-8") as token_file:
        return json.load(token_file)


def expiration_of(token):
    payload = token.split(".")[1]
    payload += "=" * (-len(payload) % 4)
    return json.loads(base64.urlsafe_b64decode(payload))["exp"]


def ssl_context():
    return ssl._create_unverified_context()


class KuraClient:

    def __init__(self, base_url, token_pair, context):
        self.base_url = base_url.rstrip("/")
        self.token_pair = token_pair
        self.context = context

    def get_framework_properties(self):
        request = urllib.request.Request(self.base_url + IMAGES_PATH, headers={
            "Authorization": "Bearer " + self.token_pair["accessToken"],
            "Accept": "application/json",
        })
        with urllib.request.urlopen(request, context=self.context) as response:
            return json.load(response)

    def refresh(self):
        request = urllib.request.Request(self.base_url + REFRESH_PATH, method="POST",
                                         data=self.token_pair["refreshToken"].encode("utf-8"),
                                         headers={"Content-Type": "text/plain", "Accept": "application/json"})
        with urllib.request.urlopen(request, context=self.context) as response:
            self.token_pair = json.load(response)

    def access_token_expires_within(self, seconds):
        return expiration_of(self.token_pair["accessToken"]) - time.time() < seconds


def main():
    base_url = os.environ["KURA_REST_BASE_URL"]
    jwt_file = os.environ["KURA_JWT_FILE"]
    interval = 10
    refresh_margin = 15

    log("Identity: " + os.environ.get("KURA_IDENTITY_NAME", "?") + ", REST base URL: " + base_url)
    client = KuraClient(base_url, read_token_pair(jwt_file), ssl_context())

    while True:
        try:
            if client.access_token_expires_within(refresh_margin):
                client.refresh()
                log("Token pair refreshed")

            properties = client.get_framework_properties()
            log("Images:\n" + json.dumps(properties, indent=2, sort_keys=True))
        except urllib.error.HTTPError as e:
            log("Request failed: HTTP " + str(e.code) + " " + e.reason)
            if e.code == 401:
                log("Access to the Kura APIs lost, exiting")
                return 1
        except urllib.error.URLError as e:
            log("Request failed: " + str(e.reason))

        time.sleep(interval)


if __name__ == "__main__":
    sys.exit(main())
